 const inside=button(scopeRow,'Preset trong hình',()=>useMask('in')),outside=button(scopeRow,'Preset ngoài hình',()=>useMask('out'));
 button(scopeRow,'Lấy nét vùng đã vẽ',()=>act('Sao chép nét vùng thành minh họa',()=>{const list=(P.adjustRegionStrokes||[]).filter(s=>s.mode==='lasso'&&s.points.length);if(!list.length)throw Error('Chưa có nét vùng. Vẽ tự do hoặc thêm hình có sẵn.');let n=Math.max(0,...state.strokes.map(s=>Number(s.id.slice(4))));state.set([...state.strokes,...list.map(s=>({...C.defaults,...style,id:'art-'+(++n),closed:!s.open,points:s.points.map(p=>p.slice())}))]);selected=state.strokes.at(-1).id;}));
 const status=document.createElement('p');status.className='ray-doodle-status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');dock.append(status);
 const entry=document.createElement('button');entry.type='button';entry.className='ray-doodle-entry';entry.setAttribute('aria-label','Vẽ minh họa');entry.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m4 17 1 4 4-1L20 9l-5-5L4 17ZM13 6l5 5M4 17l5 3"/></svg><span>Vẽ</span>';entry.onclick=()=>opened?finish():start();const tabs=document.querySelector('.editor-tabs');tabs.insertBefore(entry,tabs.querySelector('[data-tool=text]'));
 const shortcut=button(document.querySelector('.region-shape-tools .region-shape-row'),'Vẽ nét lên ảnh',()=>start());
 function current(){return state.strokes.find(s=>s.id===selected);}
 function start(){if(!source)return;P.adjustRegionDrawing=false;RayRegionPaintUI.sync();BuongToiApp.showTools('film');opened=true;notice='';sync();}
 function finish(){opened=false;ink=null;sync();queue();}
 function sync(){const show=opened&&!!source&&document.body.dataset.editorTool==='film'&&!app.classList.contains('is-result-preview');if(opened&&!show)opened=false;dock.hidden=surface.hidden=!show;if(app.classList.contains('ray-doodle-building')!==show)app.classList.toggle('ray-doodle-building',show);entry.classList.toggle('active',show);entry.setAttribute('aria-pressed',String(show));entry.disabled=shortcut.disabled=!source;
  const s=current(),v=s||style;if(s)for(const key of Object.keys(C.defaults))style[key]=s[key];for(const c of [inkColor,fillColor]){c.swatch.value=c.hex.value=v[c.key];}for(const c of [width,opacity,fillOpacity]){c.input.value=v[c.key]*c.scale;c.out.textContent=Math.round(v[c.key]*c.scale)+(c.key==='width'?'':'%');}fillSide.value=v.fillSide;
  const signature=state.strokes.map(s=>s.id+':'+s.closed).join(',');if(picker.dataset.signature!==signature){picker.replaceChildren();state.strokes.forEach((s,i)=>{const o=document.createElement('option');o.value=s.id;o.textContent=(s.closed?'Hình ':'Nét ')+(i+1);picker.append(o);});picker.dataset.signature=signature;}picker.value=selected||'';picker.disabled=!state.strokes.length;close.disabled=!s||s.closed||s.points.length<3;remove.disabled=!s;inside.disabled=outside.disabled=!s?.closed;for(const b of modes)b.setAttribute('aria-pressed',String(b.dataset.doodleTool===tool));
  status.textContent=notice||(tool==='fill'?'Chạm bên trong một hình kín để tô theo màu và phạm vi đang chọn.':'Vẽ con vật, cảnh hoặc chi tiết mắt/mũi bằng nét hở. Khép đường bao để tô hoặc chỉnh màu trong/ngoài.');surface.dataset.tool=tool;paintGuide();
 }
 function paintGuide(){svg.replaceChildren();if(surface.hidden)return;const g=bodyGeo();if(!g)return;const r=wrap.getBoundingClientRect(),W=g.W*g.k,H=g.H*g.k;Object.assign(surface.style,{left:g.ox-r.left+'px',top:g.oy-r.top+'px',width:W+'px',height:H+'px'});svg.setAttribute('viewBox','0 0 '+W+' '+H);
  function path(points,closed,cls){if(!points.length)return;const p=document.createElementNS(svg.namespaceURI,'path');p.setAttribute('d','M'+points.map(p=>p[0]*W+' '+p[1]*H).join('L')+(closed?'Z':''));p.setAttribute('class',cls);svg.append(p);}
  const s=current();if(s&&['edit','move'].includes(tool)){path(s.points,s.closed,'ray-doodle-guide');if(tool==='edit'){const step=Math.max(1,Math.ceil(s.points.length/14));for(let i=0;i<s.points.length;i+=step){const p=s.points[i],c=document.createElementNS(svg.namespaceURI,'circle');c.setAttribute('cx',p[0]*W);c.setAttribute('cy',p[1]*H);c.setAttribute('r',3);svg.append(c);}}}if(ink)path(ink.points,false,'ray-doodle-ink');
 }
 function point(e,g){return[clamp((e.clientX-g.ox)/(g.W*g.k),0,1),clamp((e.clientY-g.oy)/(g.H*g.k),0,1)];}
 function hit(p,g){const list=state.strokes.map(s=>({...s,mode:'lasso'})),edge=G.hit(list,p,g.W*g.k,g.H*g.k,20);if(edge)return edge;for(let i=list.length-1;i>=0;i--)if(C.contains(list[i],p))return{index:i,point:0};return null;}
 RayControls.bindDrag(surface,{
  start(e){if(surface.hidden||BEAUTY.busy||BODY_AI.busy)return;const g=bodyGeo();if(!g)return;const p=point(e,g);notice='';if(['edit','move','fill'].includes(tool)){const found=tool==='fill'?state.strokes.map((s,index)=>({s,index})).reverse().find(q=>C.contains(q.s,p)):hit(p,g);if(!found){notice='Chạm vào nét hoặc trong hình kín để chọn.';sync();return;}selected=state.strokes[found.index].id;if(tool==='fill'){act('Tô màu hình minh họa',()=>{if(!current().closed)throw Error('Khép hình trước khi tô màu.');patch({fill:style.fill,fillOpacity:style.fillOpacity,fillSide:style.fillSide==='out'?'out':'in'});});return;}RaySession.record();sync();return{kind:tool,source,g,start:p,before:state.strokes,index:found.index,point:found.point};}
   RaySession.record();const s=current(),last=s?.points.at(-1),prefix=s&&!s.closed&&s.points.length>1&&G.distance(last,p,g.W*g.k,g.H*g.k)<16?s.points:[];ink={points:[prefix.at(-1)||p]};paintGuide();return{kind:tool,source,g,start:ink.points[0],prefix,index:prefix.length?state.strokes.indexOf(s):-1,before:state.strokes,ink};},
  move(s,e){if(source!==s.source)return;const p=point(e,s.g);if(['edit','move'].includes(s.kind)){const old=s.before[s.index],dx=(p[0]-s.start[0])*source.width,dy=(p[1]-s.start[1])*source.height,points=s.kind==='edit'?G.bend(old.points,s.point,dx,dy,source.width,source.height,.12):G.transform(old.points,source.width,source.height,{dx,dy});state.set(s.before.map((q,i)=>i===s.index?{...q,points}:q));redraw();return;}
   if(s.kind==='free'){if(s.ink.points.length<512)s.ink.points=RayRegionPaint.append(s.ink.points,p,.0008);}else s.ink.points=G.segment(s.start,p,s.kind,source.width,source.height);paintGuide();},
  end(s){if(source!==s.source){ink=null;sync();return;}try{if(!['edit','move'].includes(s.kind)){const points=G.append(s.prefix,s.kind==='free'?C.smooth(s.ink.points):s.ink.points),old=s.index>=0?s.before[s.index]:{...style,id:nextId(),closed:false};let list=s.index>=0?s.before.map((q,i)=>i===s.index?{...q,points}:q):[...s.before,{...old,points}];const index=s.index>=0?s.index:list.length-1,joined=points.length===1?{strokes:list.map(s=>({...s,mode:'lasso',size:.006,open:!s.closed})),index}:G.join(list.map(s=>({...s,mode:'lasso',size:.006,open:!s.closed})),index,12/(s.g.W*s.g.k)*source.width,source.width,source.height);list=joined.strokes.map(({mode,size,open,...s})=>({...s,closed:!open}));state.set(list);selected=list[joined.index].id;}ink=null;redraw(true);RaySession.record('Vẽ hoặc sửa nét minh họa');}catch(e){ink=null;notice=e.message;sync();}}
 });
 const previous=render;render=function(target,src){const result=previous(target,src);if(!target.classList?.contains('roll-thumb')&&state.strokes.length){const c=target.getContext('2d'),bw=Math.max(0,(target.width-src.width)/2);c.save();c.translate(bw,bw);C.draw(c,src.width,src.height,state.capture());c.restore();}return result;};
 window.RayDoodle={capture:()=>state.capture(),restore(value){state.restore(value);selected=state.strokes.at(-1)?.id||null;opened=false;ink=null;sync();},clear(){state.clear();selected=null;opened=false;ink=null;sync();},start,finish,sync};
